-- Keep the paid part of a roadmap where free users can't read it.
--   roadmaps.steps               -> only the free preview (the first 3 steps)
--   roadmap_premium_steps.steps  -> steps 4 and up; readable only when profiles.is_premium is true
-- Row Level Security enforces this in the database, so it holds even if someone queries
-- Supabase directly with their own session instead of going through the app.

alter table public.roadmaps
  add column step_count integer not null default 0,
  -- 'ai' = generated by the model; 'built-in' = the free fallback from the built-in city data.
  add column source text not null default 'ai' check (source in ('ai', 'built-in'));

create table public.roadmap_premium_steps (
  roadmap_id uuid primary key references public.roadmaps (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  steps jsonb not null check (jsonb_typeof(steps) = 'array'),
  created_at timestamptz not null default now()
);

alter table public.roadmap_premium_steps enable row level security;

create policy "Premium users can read their locked steps"
  on public.roadmap_premium_steps for select
  to authenticated
  using (
    (select auth.uid()) = user_id
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.is_premium)
  );

-- Anyone can save locked steps for a roadmap they own. Saving doesn't let them read them back.
create policy "Users can save locked steps for their own roadmaps"
  on public.roadmap_premium_steps for insert
  to authenticated
  with check (
    (select auth.uid()) = user_id
    and exists (select 1 from public.roadmaps r where r.id = roadmap_id and r.user_id = (select auth.uid()))
  );

-- Move roadmaps saved before this migration: steps 4+ go to the locked table.
update public.roadmaps set step_count = jsonb_array_length(steps);

insert into public.roadmap_premium_steps (roadmap_id, user_id, steps)
select r.id, r.user_id,
  (select jsonb_agg(e order by ord) from jsonb_array_elements(r.steps) with ordinality as t(e, ord) where ord > 3)
from public.roadmaps r
where jsonb_array_length(r.steps) > 3;

update public.roadmaps
set steps = (select coalesce(jsonb_agg(e order by ord), '[]'::jsonb) from jsonb_array_elements(steps) with ordinality as t(e, ord) where ord <= 3)
where jsonb_array_length(steps) > 3;
